import{_ as e,o as i,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2020-03-17 :: Ceph Crimson Meeting","description":"","frontmatter":{"title":"2020-03-17 :: Ceph Crimson Meeting","date":"2020-03-17T00:00:00.000Z","updated":"2020-04-04T00:00:00.000Z","tags":["Ceph","BlueStore","OSD","Distributed Storage","BlueFS"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-03-17_-_-_Ceph_Crimson_Meeting.md","filePath":"posts/2020/2020-03-17_-_-_Ceph_Crimson_Meeting.md","lastUpdated":1780460162000}'),o={name:"posts/2020/2020-03-17_-_-_Ceph_Crimson_Meeting.md"};function r(s,l,n,u,h,p){return i(),a("div",null,[...l[0]||(l[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><p>本次Ceph Crimson会议主要讨论了Ceph分布式存储系统的研发进展，包括技术问题、解决方案和后续行动计划。会议重点涉及了Ceph BlueStore的实现、对象类（CLS）的函数实现、OSD的恢复和清理工作，以及技术问题和解决方案等议题。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Ceph BlueStore的实现</strong></p><ul><li>讨论了使用BlueJeans进行视频会议的体验，包括白板和屏幕共享功能。</li><li>分析了BlueStore的具体实现细节，如节点在树中的实现和团队讨论。</li></ul></li><li><p><strong>对象类（CLS）的函数实现</strong></p><ul><li>跟踪了CLS法律项目的进展，包括CBT更新请求和产品审查。</li><li>发现并分析了某些函数在测试中出现的回归问题。</li></ul></li><li><p><strong>OSD的恢复和清理工作</strong></p><ul><li>讨论了OSD中的恢复和清理工作，包括任务分配和具体实施。</li><li>讨论了OSD中的加密和传统T的比较，以及在恢复工作中可能遇到的问题。</li></ul></li><li><p><strong>技术问题和解决方案</strong></p><ul><li>讨论了OSD中处理OSD map消息时的问题，以及通过调试解决这些问题的方法。</li><li>提到了心跳竞赛问题和messenger连接接口的修改。</li></ul></li><li><p><strong>文档和协作</strong></p><ul><li>强调了文档的重要性，并建议在Google Docs中进行协作。</li><li>讨论了如何通过文档来协调和记录恢复和清理工作的进展。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>确认了BlueStore中的一些实现细节和团队讨论的结果。</li><li>确定了CLS法律项目的进展和需要解决的回归问题。</li><li>分配了OSD中的恢复和清理工作的具体任务。</li><li>强调了文档和协作的重要性，建议在Google Docs中进行协作。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续分析和修复CLS法律项目中的回归问题。</li><li>分配和执行OSD中的恢复和清理工作的具体任务。</li><li>在Google Docs中进行文档协作，记录和协调工作进展。</li><li>继续测试和优化BlueStore的实现。</li></ul><h4 id="关键词" tabindex="-1">关键词 <a class="header-anchor" href="#关键词" aria-label="Permalink to &quot;关键词&quot;">​</a></h4><ul><li>Ceph</li><li>BlueStore</li><li>CLS law</li><li>OSD</li><li>恢复工作</li><li>清理工作</li><li>Google Docs</li><li>文档协作</li></ul>',11)])])}const c=e(o,[["render",r]]);export{d as __pageData,c as default};
